<?php $title='Add Post';require __DIR__.'/_layout.php';if(!can_manage('posts'))exit('Forbidden');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$titlev=trim($_POST['title']);$slug=unique_slug(slugify($_POST['slug']?:$titlev));$st=db()->prepare("INSERT INTO posts(title,slug,excerpt,content,category_id,author_id,status,published_at,seo_title,seo_description) VALUES(?,?,?,?,?,?,?,?,?,?)");$pub=$_POST['published_at']?:date('Y-m-d H:i:s');$st->execute([$titlev,$slug,trim($_POST['excerpt']),$_POST['content'],(int)($_POST['category_id']?:0),current_user()['id'],$_POST['status'],$pub,trim($_POST['seo_title']),trim($_POST['seo_description'])]);log_activity(current_user()['id'],'created','post',(int)db()->lastInsertId());flash('success','Post created.');redirect('posts.php');} ?><h1>Add Post</h1><?php include __DIR__.'/_post_form.php'; require __DIR__.'/_footer.php';